{"implementation":"def solve(case):
    if not isinstance(case, dict):
        raise ValueError('case must be an object')
    if set(case) - {'nodes', 'required_symbols', '_case_nonce', 'schema_version', 'task_id', 'registry_id'}:
        raise ValueError('unexpected case field')
    if 'nodes' not in case or 'required_symbols' not in case:
        raise ValueError('missing required field')
    nodes = case['nodes']
    required_symbols = case['required_symbols']
    if not isinstance(nodes, list) or not isinstance(required_symbols, list):
        raise ValueError('invalid required field')
    if not all(isinstance(symbol, str) for symbol in required_symbols):
        raise ValueError('invalid required_symbols')

    by_id = {}
    children = {}
    required_fields = {'id', 'parent', 'symbol', 'depth', 'removable', 'utility'}
    for node in nodes:
        if not isinstance(node, dict) or not required_fields.issubset(node):
            raise ValueError('invalid node')
        node_id = node['id']
        parent = node['parent']
        if (not isinstance(node_id, str) or not isinstance(node['symbol'], str) or
                (parent is not None and not isinstance(parent, str)) or
                not isinstance(node['depth'], int) or isinstance(node['depth'], bool) or
                not isinstance(node['removable'], bool) or
                not isinstance(node['utility'], (int, float)) or isinstance(node['utility'], bool) or
                node_id in by_id):
            raise ValueError('invalid node field')
        by_id[node_id] = node
        children[node_id] = []
    for node_id, node in by_id.items():
        parent = node['parent']
        if parent is not None:
            if parent not in by_id:
                raise ValueError('unknown parent')
            children[parent].append(node_id)

    required = set(required_symbols)
    candidates = sorted(by_id.values(), key=lambda node: (-node['depth'], node['id']))
    removed = []
    retained = set(by_id)
    for node in candidates:
        node_id = node['id']
        if (not node['removable'] or node['parent'] is None or
                node['symbol'] in required):
            continue
        if any(child_id in retained for child_id in children[node_id]):
            continue
        symbols_after = {by_id[other_id]['symbol'] for other_id in retained if other_id != node_id}
        if not required.issubset(symbols_after):
            continue
        retained.remove(node_id)
        removed.append(node_id)
    return {'removed_node_ids': removed, 'retained_node_ids': sorted(retained)}
